import numpy as np

def normalize(x):
    return x / np.linalg.norm(x, axis=1, keepdims=True)

queries = normalize(np.array([[1.0, 0.1], [0.2, 1.0], [0.7, 0.7]]))
gallery = normalize(np.array([[0.9, 0.2], [1.0, 0.0], [0.1, 1.0], [0.6, 0.8], [0.8, 0.6]]))
answer = [0, 2, 3]  # 질의마다 정답 상품 번호

ranks = np.argsort(-(queries @ gallery.T), axis=1)  # 코사인 유사도 높은 순

def recall_at_k(k):
    return np.mean([answer[i] in ranks[i, :k] for i in range(len(answer))])

def mrr():
    return np.mean([1 / (list(ranks[i]).index(answer[i]) + 1) for i in range(len(answer))])

print("Recall@1 =", round(recall_at_k(1), 3))  # 0.333
print("Recall@3 =", round(recall_at_k(3), 3))  # 1.0
print("MRR      =", round(mrr(), 3))          # 0.667

import json

ALLOWED = {
    "color": {"블랙", "화이트", "네이비", "그레이", "베이지"},
    "neck": {"라운드넥", "브이넥", "터틀넥", "카라"},
    "sleeve": {"반팔", "긴팔", "민소매"},
}
THRESHOLD = 0.85
raw = '{"color": ["네이비", 0.97], "neck": ["헨리넥", 0.91], "sleeve": ["긴팔", 0.62]}'

def route(raw):
    out = json.loads(raw)
    auto, review = {}, {}
    for key, allowed in ALLOWED.items():
        if key not in out:
            review[key] = "빠짐"
            continue
        value, conf = out[key]
        if value not in allowed:
            review[key] = f"사전에 없는 값: {value}"
        elif conf < THRESHOLD:
            review[key] = f"확신 낮음: {value} ({conf})"
        else:
            auto[key] = value
    return auto, review

auto, review = route(raw)
print("자동 반영:", auto)
print("검수 대기:", review)
# 자동 반영: {'color': '네이비'}
# 검수 대기: {'neck': '사전에 없는 값: 헨리넥', 'sleeve': '확신 낮음: 긴팔 (0.62)'}
